package org.brightstats.stats;
import java.util.*;
import java.util.function.IntConsumer;
/** Hierarchical PLSc moment propagation with original-case full-pipeline inference. */
public final class FactorHierarchy {
 private FactorHierarchy(){}
 public record Stage(HigherOrderPls.Specification specification,List<String> inputNames,double[][] inputCorrelation,List<PlsSem.Block> blocks,double[][] weights,double[][] loadings,double[] reliabilities,double[][] correlations,double[][] paths,double[] rSquared,int iterations,boolean converged,List<String>warnings){public Stage{inputNames=List.copyOf(inputNames);inputCorrelation=Matrices.copy(inputCorrelation);blocks=List.copyOf(blocks);weights=Matrices.copy(weights);loadings=Matrices.copy(loadings);reliabilities=reliabilities.clone();correlations=Matrices.copy(correlations);paths=Matrices.copy(paths);rSquared=rSquared.clone();warnings=List.copyOf(warnings);}@Override public double[][] inputCorrelation(){return Matrices.copy(inputCorrelation);}@Override public double[][] weights(){return Matrices.copy(weights);}@Override public double[][] loadings(){return Matrices.copy(loadings);}@Override public double[] reliabilities(){return reliabilities.clone();}@Override public double[][] correlations(){return Matrices.copy(correlations);}@Override public double[][] paths(){return Matrices.copy(paths);}@Override public double[] rSquared(){return rSquared.clone();}}
 public record Fit(HierarchyPipeline.Model model,int observations,int originalColumns,ConsistentPls.Fit firstStage,List<Stage> stages,List<Bootstrap.Parameter> parameters,double[] estimates,List<String>warnings){public Fit{stages=List.copyOf(stages);parameters=List.copyOf(parameters);estimates=estimates.clone();warnings=List.copyOf(warnings);}@Override public double[] estimates(){return estimates.clone();}}
 public record Resampled(Fit point,Bootstrap.Result inference){}
 public static Fit fit(double[][] data,HierarchyPipeline.Model model){return compute(data,model,null,null);}
 private static Fit compute(double[][] data,HierarchyPipeline.Model model,Fit reference,int[] rows){int width=Matrices.width(data,3);for(var block:model.blocks())if(block.measurementType()==PlsSem.MeasurementType.REFLECTIVE&&(block.mode()!=PlsSem.Mode.A||block.columns().length<3))throw new IllegalArgumentException("Hierarchical factor correction requires ModeA reflective source factors with at least three indicators; formative composites remain separate.");var first=ConsistentPls.fit(data,model.blocks(),model.edges(),model.options());if(!first.composite().converged())throw new IllegalArgumentException("Source PLSc did not converge.");double[][] input=first.correlations();if(reference!=null){double[] signs=Bootstrap.alignment(first.composite().scores(),reference.firstStage().composite().scores(),rows);for(int i=0;i<input.length;i++)for(int j=0;j<input.length;j++)input[i][j]*=signs[i]*signs[j];}List<String> names=model.blocks().stream().map(PlsSem.Block::name).toList();List<PlsSem.MeasurementType> types=model.blocks().stream().map(PlsSem.Block::measurementType).toList();List<PlsSem.Edge> edges=model.edges();List<Stage> stages=new ArrayList<>();List<String>warnings=new ArrayList<>(first.warnings());List<Bootstrap.Parameter> parameters=List.of();double[] estimates=new double[0];for(int level=0;level<model.stages().size();level++){Matrices.interrupted();var specification=model.stages().get(level);int k=names.size();List<PlsSem.Block> proxies=new ArrayList<>();for(int i=0;i<k;i++)proxies.add(new PlsSem.Block(names.get(i),new int[]{i},PlsSem.Mode.A));HigherOrderPls.validate(k,proxies,edges,specification);for(var higher:specification.higherOrder())if(higher.measurementType()==PlsSem.MeasurementType.REFLECTIVE&&(higher.mode()!=PlsSem.Mode.A||higher.lowerOrder().length<3))throw new IllegalArgumentException("A reflective higher-order factor needs ModeA and at least three lower-order variables in this moment contract.");List<PlsSem.Block> blocks=new ArrayList<>();for(int retained:specification.retained())blocks.add(new PlsSem.Block(names.get(retained),new int[]{retained},PlsSem.Mode.A,null,types.get(retained)));for(var higher:specification.higherOrder())blocks.add(new PlsSem.Block(higher.name(),higher.lowerOrder(),higher.mode(),higher.initialWeights(),higher.measurementType()));var fit=ConsistentPls.fit(MomentDesign.correlation(input),blocks,specification.edges(),specification.options());if(!fit.composite().converged())throw new IllegalArgumentException("Higher-order moment PLSc did not converge.");double[][] weights=fit.composite().weights(),loadings=fit.loadings(),paths=fit.paths(),correlations=fit.correlations();double[] signs=new double[blocks.size()];Arrays.fill(signs,1);if(reference!=null){var ref=reference.stages().get(level);double[][] rw=ref.weights();for(int j=0;j<blocks.size();j++){int[] cols=blocks.get(j).columns();double dot=0,a=0,b=0;for(int u=0;u<cols.length;u++)for(int v=0;v<cols.length;v++){double r=input[cols[u]][cols[v]];dot+=weights[j][u]*r*rw[j][v];a+=weights[j][u]*r*weights[j][v];b+=rw[j][u]*r*rw[j][v];}if(!Double.isFinite(dot)||Math.abs(dot)<=1e-8*Math.sqrt(a*b))throw new IllegalArgumentException("Ambiguous higher-order moment sign alignment.");signs[j]=dot<0?-1:1;}}for(int j=0;j<blocks.size();j++){for(int v=0;v<weights[j].length;v++){weights[j][v]*=signs[j];loadings[j][v]*=signs[j];}for(int l=0;l<blocks.size();l++){paths[j][l]*=signs[j]*signs[l];correlations[j][l]*=signs[j]*signs[l];}}var stage=new Stage(specification,names,input,blocks,weights,loadings,fit.reliabilities(),correlations,paths,fit.rSquared(),fit.composite().iterations(),true,fit.warnings());stages.add(stage);for(String warning:stage.warnings())warnings.add("Moment transition "+(level+1)+": "+warning);List<Bootstrap.Parameter> targets=new ArrayList<>(Bootstrap.parameters(blocks,specification.edges()));for(int j=0;j<blocks.size();j++){if(Double.isFinite(stage.rSquared[j]))targets.add(new Bootstrap.Parameter("R squared",j,j,-1,blocks.get(j).name()));if(blocks.get(j).columns().length>1&&blocks.get(j).measurementType()==PlsSem.MeasurementType.REFLECTIVE)targets.add(new Bootstrap.Parameter("Higher-order rho A",j,j,-1,blocks.get(j).name()));for(int pair=j+1;pair<blocks.size();pair++)targets.add(new Bootstrap.Parameter("Corrected correlation",j,pair,-1,blocks.get(j).name()+" / "+blocks.get(pair).name()));}parameters=List.copyOf(targets);estimates=vector(stage,parameters);input=correlations;names=blocks.stream().map(PlsSem.Block::name).toList();edges=specification.edges();types=blocks.stream().map(PlsSem.Block::measurementType).toList();}
 warnings.add("Independent hierarchical PLSc moment contract: source measurement reliability is corrected before higher-order estimation; each reflective higher-order factor is corrected again for its own lower-order unique variance. Formative higher-order constructs remain composites. This is not a claim of native numerical parity.");warnings.add("Retained inputs are already corrected construct-level correlations. Their singleton stage roles denote those input variables, not a claim that their original raw indicators have perfect reliability. All original source definitions and reliabilities remain retained.");warnings.add("Covariance-equivalent rows only reuse moment solvers. No artificial individual scores, artificial sample size, score prediction or ordinary case-score fit tests are exposed. Case/jackknife inference refits all levels from original observations; inadmissible reliability or non-PD matrices fail without repair.");return new Fit(model,data.length,width,first,stages,parameters,estimates,warnings);}
 private static double[] vector(Stage stage,List<Bootstrap.Parameter> parameters){int m=stage.blocks().size();double[][] b=new double[m][m],total=new double[m][m],power=new double[m][m];for(var edge:stage.specification().edges()){b[edge.source()][edge.target()]=stage.paths[edge.source()][edge.target()];total[edge.source()][edge.target()]=b[edge.source()][edge.target()];power[edge.source()][edge.target()]=b[edge.source()][edge.target()];}for(int len=2;len<m;len++){double[][] next=new double[m][m];for(int i=0;i<m;i++)for(int j=0;j<m;j++)for(int k=0;k<m;k++)next[i][j]+=power[i][k]*b[k][j];for(int i=0;i<m;i++)for(int j=0;j<m;j++)total[i][j]+=next[i][j];power=next;}double[] values=new double[parameters.size()];for(int t=0;t<values.length;t++){var p=parameters.get(t);if(p.column()>=0){int k=0;while(stage.blocks().get(p.source()).columns()[k]!=p.column())k++;values[t]=p.family().equals("Weight")?stage.weights[p.source()][k]:stage.loadings[p.source()][k];}else values[t]=switch(p.family()){case "Path"->b[p.source()][p.target()];case "Total effect"->total[p.source()][p.target()];case "Total indirect effect"->total[p.source()][p.target()]-b[p.source()][p.target()];case "R squared"->stage.rSquared[p.source()];case "Higher-order rho A"->stage.reliabilities[p.source()];case "Corrected correlation"->stage.correlations[p.source()][p.target()];default->throw new IllegalArgumentException("Unknown hierarchy parameter: "+p.family());};}return values;}
 public static Resampled bootstrap(double[][] data,HierarchyPipeline.Model model,Bootstrap.Options settings,IntConsumer progress){if(settings.convention()!=RegressionBootstrap.Convention.STANDARD)throw new IllegalArgumentException("Hierarchy inference supports standard percentile/genuine BCa, not legacy PLS interval conventions.");Fit point=fit(data,model);var result=Resampling.run(data,point.parameters(),point.estimates(),settings,(sample,rows)->compute(sample,model,point,rows).estimates(),progress,"Hierarchical PLSc moments","Every original-case/jackknife draw refits raw source PLSc, corrects its factor/composite correlations, refits every higher-order moment level and aligns orientation before passing correlations onward. Artificial covariance-equivalent rows are never resampled.");result=Resampling.suppressTests(result,p->p.family().equals("R squared")||p.family().equals("Higher-order rho A"),"Bounded R-squared/reliability parameters do not receive generic ratio tests against zero; empirical intervals are retained.");List<String>warnings=new ArrayList<>(result.warnings());warnings.addAll(point.warnings());return new Resampled(point,new Bootstrap.Result(result.options(),result.method(),result.randomGenerator(),result.signHandling(),result.successful(),result.failed(),result.failures(),result.estimates(),warnings,result.estimator()));}
}
